import json
D=[]
def add(c,t,a,b,core,example,trap):D.append(dict(ch=c,title=t,start=a,end=b,core=core.split('||'),example=example,trap=trap))
add(1,'Khách hàng, người mua và người tiêu dùng',7,11,'Hành vi khách hàng bao gồm hoạt động tinh thần, cảm xúc và thể chất khi lựa chọn, mua, sử dụng và xử lý sản phẩm để thỏa mãn nhu cầu. Phạm vi nghiên cứu kéo dài trước, trong và sau mua.||Người mua trực tiếp thực hiện giao dịch; người tiêu dùng sử dụng sản phẩm; khách hàng là cá nhân hoặc tổ chức có quan hệ mua với doanh nghiệp. Một người có thể đảm nhiệm nhiều vai trò.||Tiếp cận thực chứng tìm quy luật và kiểm định bằng dữ liệu; tiếp cận diễn giải tìm hiểu ý nghĩa và trải nghiệm của người tiêu dùng. Đây là diễn giải bổ trợ cho hai trường phái được liệt kê trong slide.','Mẹ mua sữa cho con: mẹ là người mua, con là người tiêu dùng. Truyền thông cần thuyết phục mẹ về an toàn và tạo trải nghiệm phù hợp với trẻ.','Hành vi khách hàng không chỉ là thao tác thanh toán; người dùng chưa chắc là người mua.')
add(1,'Phân loại và quan hệ khách hàng',12,15,'Khách hàng cá nhân mua cho bản thân hoặc hộ gia đình; khách hàng tổ chức mua để vận hành, sản xuất, bán lại hoặc phục vụ chức năng tổ chức.||So sánh theo mục đích, quy mô mua và nguồn ngân sách. Cùng một sản phẩm có thể được mua trong hai thị trường khác nhau.||Slide phân loại quan hệ: Suspect → Prospect → Lead → Client → Supporter → Advocate → Member → Partner. Hãy dùng nội hàm trong bảng slide 15 khi ôn học phần này.','Một người mua máy tính cho gia đình là khách hàng cá nhân; phòng mua sắm mua 100 máy để trang bị văn phòng là khách hàng tổ chức.','Không phân loại chỉ bằng tên sản phẩm hoặc số lượng; mục đích sử dụng là căn cứ quan trọng.')
add(1,'Bức tranh các yếu tố ảnh hưởng',16,20,'Khách hàng cá nhân chịu ảnh hưởng của văn hóa, xã hội, cá nhân và tâm lý; tình huống làm thay đổi cách các yếu tố này biểu hiện.||Văn hóa liên quan giá trị và chuẩn mực; xã hội gồm nhóm tham khảo, gia đình, giai tầng; cá nhân gồm tuổi, nghề nghiệp, lối sống; tâm lý gồm động cơ, nhận thức, học hỏi, thái độ.||Với tổ chức, cần xét người tham gia mua, trung tâm mua và hoạt động thu mua. Bảng theo thập kỷ trong slide là nội dung minh họa của bài giảng, không phải dự báo cho mọi khách hàng hiện nay.','Sinh viên mua giày vì bạn bè giới thiệu (xã hội), thích thể thao (lối sống), và tin giày đắt bền hơn (nhận thức).','Một quyết định thường có nhiều nguyên nhân; tránh buộc toàn bộ tình huống vào một yếu tố duy nhất.')
add(1,'Nghiên cứu hành vi và ứng dụng marketing',21,30,'Nghiên cứu phản ứng khách hàng, yếu tố ảnh hưởng và tác động của hoạt động marketing. Nội dung gồm đặc điểm, thói quen tiêu dùng, nhận thức thương hiệu và cách tiếp nhận quảng cáo.||Chọn phương pháp theo câu hỏi: quan sát cho biết hành vi, phỏng vấn tìm hiểu ý nghĩa, khảo sát mô tả quy mô; thực nghiệm kiểm tra quan hệ nhân quả khi kiểm soát được yếu tố khác. Các ví dụ phương pháp là hướng dẫn vận dụng.||Kết quả hỗ trợ phân khúc, lựa chọn thị trường và quyết định sản phẩm, giá, phân phối, chiêu thị. Nghiên cứu cũng giúp triển khai marketing xã hội và tiêu dùng thông thái.','Đổi hai mẫu bao bì trong điều kiện tương đương, phân nhóm ngẫu nhiên và so sánh lựa chọn là thiết kế thực nghiệm minh họa.','Quan sát thấy hai biến cùng tăng chưa đủ kết luận quan hệ nhân quả.')
add(2,'Văn hóa và văn hóa tiêu dùng',34,45,'Văn hóa gồm niềm tin, giá trị và phong tục định hướng hành vi trong xã hội. Văn hóa tiêu dùng tập trung vào biểu hiện của những yếu tố đó trong lựa chọn và sử dụng sản phẩm.||Giá trị là điều được xem là đáng coi trọng; chuẩn mực là quy tắc hướng dẫn hành vi; phong tục là thói quen được cộng đồng duy trì lâu đời. Biểu tượng và ngôn ngữ giúp truyền tải ý nghĩa văn hóa.||Văn hóa được học hỏi, lưu truyền và có tính thích nghi; thay đổi thường cần thời gian. Khi đọc slide 43, cần phân biệt đồ tạo tác vật chất với giá trị phi vật thể: cách dùng từ trong slide có điểm chưa nhất quán.','Giá trị kính trọng người lớn dẫn đến chuẩn mực biếu quà phù hợp và biểu hiện thành phong tục tặng quà dịp Tết.','Giá trị, chuẩn mực và phong tục liên quan với nhau nhưng không đồng nghĩa.')
add(2,'Nhánh văn hóa và thị trường quốc tế',46,48,'Nhánh văn hóa là nhóm có đặc trưng trong một nền văn hóa rộng hơn, chia sẻ niềm tin, giá trị hoặc phong tục riêng.||Có thể xét nhánh văn hóa theo dân tộc, khu vực, tuổi tác, giới tính như bài giảng. Dùng dữ liệu thực tế để xác định khác biệt tiêu dùng có ý nghĩa.||Marketing quốc tế cân nhắc thích nghi với từng thị trường, tiêu chuẩn hóa hoặc tác động đến thay đổi văn hóa. Cần xem mức độ tương đồng nhu cầu và ý nghĩa của thông điệp.','Một thương hiệu giữ nhận diện chung nhưng thay khẩu vị và nội dung lễ hội theo từng thị trường.','Không mặc định mọi thành viên một nhóm đều tiêu dùng giống nhau.')
add(2,'Nhóm xã hội và nhóm tham khảo',49,59,'Nhóm xã hội có ít nhất hai người tương tác vì mục tiêu chung hoặc riêng; thành viên có vai trò, địa vị và bản sắc nhóm. Phân biệt nhóm sơ cấp/thứ cấp và nhóm thành viên với các nhóm khác.||Nhóm tham khảo là nhóm hoặc cá nhân được dùng làm điểm đối chiếu khi hình thành thái độ và hành vi; không nhất thiết phải là nhóm mình đang thuộc về.||Ảnh hưởng có thể đến từ tìm kiếm thông tin, mong muốn được chấp nhận hoặc thể hiện giá trị. Uy tín, chuyên môn, sự hấp dẫn và kinh nghiệm sản phẩm làm thay đổi mức ảnh hưởng.','Người chạy bộ nghe chuyên gia tư vấn giày vì tin kiến thức; chọn đồng phục câu lạc bộ để thể hiện sự thuộc về nhóm.','Người nổi tiếng không luôn có chuyên môn; nhiều lượt theo dõi chưa bảo đảm độ tin cậy.')
add(2,'Gia đình, vai trò mua và vòng đời',60,64,'Gia đình ảnh hưởng mạnh đến học hỏi và tiêu dùng. Quy mô hộ, số con, vai trò thành viên và điều kiện sống làm thay đổi nhu cầu.||Một quyết định mua có thể phân chia người đề xuất, người ảnh hưởng, người quyết định, người mua và người sử dụng. Không mặc định vai trò theo giới.||Chu kỳ đời sống gia đình gắn với thay đổi nhu cầu, thu nhập và trách nhiệm. Trẻ em có thể chi tiêu trực tiếp, ảnh hưởng mua và trở thành khách hàng tương lai.','Con đề xuất mua laptop, anh tư vấn cấu hình, cha mẹ thống nhất ngân sách, mẹ đặt hàng, con sử dụng.','Người thanh toán không nhất thiết là người quyết định tất cả thuộc tính.')
add(2,'Giai tầng và ứng dụng yếu tố xã hội',65,71,'Giai tầng là nhóm có địa vị tương đương; xác định bằng nhiều yếu tố như học vấn, nghề nghiệp, thu nhập và tài sản.||Các nhóm có thể khác nhau về lựa chọn sản phẩm, biểu tượng địa vị và nguồn thông tin. Đây là xu hướng cần kiểm chứng, không phải quy luật áp dụng cho từng cá nhân.||Marketing có thể dùng chuyên gia, người nổi tiếng, khách hàng quen và truyền thông phù hợp để tạo tham khảo; cần minh bạch và tránh chứng thực sai.','Thương hiệu thiết bị chuyên dụng dùng đánh giá từ người có chuyên môn thay vì chỉ nhấn mạnh sự nổi tiếng.','Thu nhập cao không đủ để suy ra mọi khía cạnh giai tầng hoặc thị hiếu.')
add(2,'Tình huống giao tiếp, mua, dùng và thải hồi',72,85,'Ảnh hưởng tình huống gắn với thời gian, địa điểm và hoàn cảnh cụ thể; cùng một người có thể lựa chọn khác nhau trong các bối cảnh.||Phân biệt tình huống tiếp nhận truyền thông, trạng thái, mua hàng, sử dụng và thải hồi. Đặc điểm tình huống gồm môi trường vật lý, xã hội, thời gian, nhiệm vụ và trải nghiệm trước đó theo slide 82.||Nghi lễ và lễ hội tạo dịp tiêu dùng có ý nghĩa biểu tượng. Thải hồi mở cơ hội thu hồi, tái sử dụng hoặc đổi sản phẩm cũ.','Mua cà phê để học một mình khác mua để tiếp khách; chương trình đổi điện thoại cũ tác động vào khâu thải hồi.','Giảm giá chỉ là một kích thích; thời gian gấp và người đi cùng cũng có thể đổi quyết định.')
add(2,'Các tình huống và mức độ quen thuộc khi mua',86,91,'Hàng giá trị thấp, mua thường xuyên thường gắn với thói quen và ít tìm kiếm thông tin.||Khi thương hiệu mới hoặc sản phẩm hoàn toàn mới, khách hàng cần thông tin và hỗ trợ để giảm bất định. Phân biệt quen loại sản phẩm với quen nhãn hiệu.||Mua tình cờ có thể chịu tác động của cảm xúc, bao bì và trưng bày. Chọn giải pháp marketing theo mức hiểu biết và bối cảnh mua.','Mua lại kem đánh răng quen thuộc khác lần đầu mua máy ảnh chuyên nghiệp; một quầy hàng hấp dẫn có thể tạo mua ngẫu hứng.','Giá thấp không tự động đồng nghĩa mua bốc đồng; nhiều giao dịch giá thấp vẫn theo kế hoạch.')
add(3,'Nhu cầu, mong muốn, mục tiêu và Hull',95,103,'Nhu cầu là trạng thái thiếu hụt; mong muốn là cách cụ thể muốn thỏa mãn thiếu hụt; mục tiêu là kết quả hướng tới. Động lực thúc đẩy hành động.||Mục tiêu phụ thuộc trải nghiệm, chuẩn mực, năng lực và khả năng tiếp cận. Nhiều nhu cầu có thể cùng tồn tại và xung đột.||Thuyết giảm động lực Hull giải thích thiếu hụt sinh lý gây căng thẳng, hành vi giúp khôi phục cân bằng; hành vi có hiệu quả có thể được lặp lại. Động lực thứ cấp được học hỏi và có thể hỗ trợ thỏa mãn nhu cầu sơ cấp.','Khát là nhu cầu; muốn uống một nhãn nước cụ thể là mong muốn; tìm được đồ uống phù hợp là mục tiêu.','Hull không giải thích trọn vẹn mọi hành vi khám phá hoặc tìm kiếm kích thích.')
add(3,'Maslow, Murray, Sheth và McClelland',104,109,'Maslow tổ chức nhu cầu thành sinh lý, an toàn, xã hội, được tôn trọng/thể hiện bản thân và tự hoàn thiện/khẳng định bản thân theo cách ghi của slide. Một sản phẩm có thể đáp ứng nhiều tầng.||Murray và Edwards trong slide nhấn mạnh các nhu cầu có thể đồng thời tồn tại, tương hỗ hoặc mâu thuẫn, không nhất thiết theo thứ bậc. Xem đầy đủ danh mục trong nguồn gốc.||Sheth nêu chức năng, xã hội, tình cảm, nhận thức và tình huống. McClelland tập trung thành tích, quyền lực và liên kết. Dùng lý thuyết để giải thích dữ kiện, không gắn nhãn người mua một cách máy móc.','Khóa học có thể đáp ứng nhu cầu thành tích; câu lạc bộ đáp ứng liên kết; đồ uống mới thu hút vì tò mò, tức giá trị nhận thức trong hệ Sheth.','Giá trị nhận thức trong hệ Sheth liên quan khám phá, không đồng nhất với toàn bộ quá trình nhận thức ở mục 3.2.')
add(3,'Cảm xúc, động cơ và đo lường',110,118,'Theo mô hình được giới thiệu, cảm xúc gắn với kích thích sinh lý và diễn giải nhận thức. Cảm xúc làm thay đổi chú ý, đánh giá và hành động.||Mua sắm có động cơ cá nhân như giải trí, khám phá; và động cơ xã hội như giao tiếp, vị thế hoặc thuộc về nhóm. Một sản phẩm có thể được truyền thông bằng nhiều lợi ích.||Động cơ là yếu tố ẩn; tự báo cáo có giới hạn. Kết hợp thang đo, quan sát, phỏng vấn sâu, nhóm tập trung, liên tưởng và kể chuyện để tìm hiểu.','Mua giày có thể vừa để vận động, vừa tự thưởng, vừa tham gia nhóm chạy; hỏi duy nhất “vì sao mua?” có thể bỏ sót động cơ.','Không suy ra chính xác động cơ nội tâm từ một hành động đơn lẻ.')
add(3,'Cảm giác, nhận thức và các ngưỡng',119,123,'Cảm giác là phản ứng trực tiếp của giác quan; nhận thức là lựa chọn, tổ chức và diễn giải kích thích để tạo ý nghĩa.||Nhận thức phụ thuộc người nhận, đối tượng và tình huống, mang tính chủ quan. Hai người có thể hiểu cùng một quảng cáo khác nhau.||Ngưỡng tuyệt đối là mức kích thích tối thiểu có thể nhận ra; ngưỡng vi sai là khác biệt nhỏ nhất có thể nhận ra. Luật Weber mô tả mức thay đổi cần thiết tăng theo cường độ ban đầu.','Cùng giảm 10.000 đồng dễ được chú ý với sản phẩm 50.000 đồng hơn sản phẩm 5 triệu đồng: ví dụ minh họa về thay đổi tương đối.','Thấy bao bì màu xanh là cảm giác; suy ra sản phẩm thân thiện môi trường là diễn giải nhận thức, chưa phải chứng cứ.')
add(3,'Xử lý thông tin và ứng dụng nhận thức',124,127,'Quy trình gồm tiếp nhận, chú ý, tổ chức/giải nghĩa, ghi nhớ, hình thành nhận thức và tác động đến hành vi. Mỗi bước có thể làm mất hiệu quả thông điệp.||Chất lượng cảm nhận chịu ảnh hưởng tín hiệu bên trong như vị, chất liệu và tín hiệu bên ngoài như thương hiệu, bao bì, không gian.||Giá tham khảo, công bằng giá và rủi ro cảm nhận ảnh hưởng lựa chọn. Trong bán lẻ cần bảo đảm tiếp xúc, chú ý, hiểu đúng và ghi nhớ.','Một cửa hàng có bao bì đẹp giúp thu hút nhưng thông tin khó đọc khiến khách không hiểu lợi ích: vấn đề ở bước giải nghĩa.','Chất lượng cảm nhận không đồng nghĩa chất lượng kỹ thuật thực tế.')
add(3,'Bản chất và các điều kiện học hỏi',128,133,'Học hỏi là thay đổi hành vi từ kiến thức và kinh nghiệm qua trải nghiệm, quan sát hoặc thông tin. Có học hỏi thụ động và tự giác.||Bốn thành phần được nêu: động lực, gợi ý, phản hồi và gia cố. Mức quan trọng, thông điệp, tâm trạng, hài lòng, lặp lại và hình ảnh ảnh hưởng mức học.||Cần xét quên, suy diễn/khái quát hóa và môi trường ứng dụng. Học trong bối cảnh gần thực tế có thể hỗ trợ nhớ lại khi mua.','Sau trải nghiệm giao hàng tốt, khách nhớ cửa hàng và chọn lại khi cần; logo là gợi ý để truy xuất trí nhớ.','Tiếp xúc nhiều lần không bảo đảm khách hiểu hoặc thích thông điệp.')
add(3,'Cổ điển, tưởng thưởng, quan sát và lập luận',134,148,'Điều kiện hóa cổ điển tạo liên kết giữa kích thích và phản ứng cảm xúc qua lặp lại. Mở rộng thương hiệu có thể tận dụng khái quát hóa nhưng cũng làm lan truyền liên tưởng xấu.||Điều kiện hóa tưởng thưởng củng cố hành vi bằng kết quả tích cực: chất lượng tốt, quà, tích điểm hoặc trải nghiệm thuận tiện. Phân biệt thưởng mỗi lần, theo số lần cố định và bất kỳ.||Học qua quan sát dựa vào hành vi và kết quả của người khác. Học bằng lập luận xử lý, liên kết thông tin để rút ra hiểu biết. Đo bằng nhận dạng, nhớ thương hiệu, trung thành và tài sản thương hiệu.','Nhạc vui đi kèm logo: cổ điển. Mua đủ 10 ly được tặng 1 ly: tưởng thưởng. Làm theo video người dùng: quan sát. So sánh cấu hình: lập luận.','Có người nổi tiếng trong quảng cáo chưa đủ kết luận quan sát; phải xem người học có bắt chước hành vi hay chỉ hình thành liên tưởng cảm xúc.')
add(3,'Thái độ: ba thành phần và chức năng',149,160,'Thái độ thể hiện đánh giá tích cực, trung tính hoặc tiêu cực đối với đối tượng. Nó được học hỏi và tương đối ổn định, nhưng có thể chịu ảnh hưởng tình huống.||Ba thành phần: nhận thức/niềm tin, cảm xúc và khuynh hướng hành vi. “Biết tiết kiệm điện”, “thích thương hiệu”, “định mua” thuộc các thành phần khác nhau.||Chức năng gồm thực dụng, bảo vệ bản ngã, biểu hiện giá trị và tri thức. Có thể đo niềm tin bằng tiêu chí, cảm xúc bằng thang đánh giá và khuynh hướng bằng ý định mua/giới thiệu.','Khách biết xe điện tiết kiệm, thích thiết kế, định mua nhưng chưa đủ ngân sách. Ba thành phần thái độ không bảo đảm hành vi mua xảy ra.','Thành phần hành vi có thể được đo bằng ý định; ý định vẫn khác hành động thực tế.')
add(3,'Mô hình thái độ và thay đổi thái độ',161,169,'Đa thuộc tính xem xét niềm tin về thuộc tính và mức đánh giá thuộc tính. TRA gắn thái độ, chuẩn chủ quan với ý định; TPB bổ sung nhận thức kiểm soát hành vi. Phần giải thích TRA là diễn giải hỗ trợ sơ đồ trong slide.||Slide 162 giới thiệu MODE qua động lực và cơ hội, cùng thái độ rõ ràng/ngầm. Khi làm bài theo môn, đối chiếu cách diễn đạt trực tiếp với giảng viên. Các mô hình cố gắng tiêu thụ và thái độ với quảng cáo giúp lý giải rào cản hoặc tác động truyền thông.||Đổi thái độ bằng thông tin mới, trải nghiệm cảm xúc tích cực, dùng thử, cải tiến giá trị hoặc thay tiêu chí đánh giá. Nguồn tin cậy, chuyên môn và cách khơi gợi cảm xúc ảnh hưởng hiệu quả.','Khách thích thương hiệu nhưng khó tiếp cận điểm bán: cải thiện phân phối có thể giúp ý định thành hành vi hơn là chỉ quảng cáo thêm.','Không đánh đồng thái độ, ý định và hành vi; bảng tính đa thuộc tính trong phòng thực hành là công cụ minh họa.')
add(4,'Tuổi, thế hệ, giáo dục và vòng đời',174,178,'Nhu cầu và sản phẩm tìm kiếm thay đổi theo giai đoạn cuộc đời. Tuổi và vòng đời gia đình cần được xem cùng trách nhiệm và điều kiện sống.||Thế hệ chia sẻ một số trải nghiệm trong cùng bối cảnh lịch sử; không thể suy ra mọi sở thích chỉ từ năm sinh. Giáo dục ảnh hưởng cách tiếp nhận thông tin và điều kiện nghề nghiệp.||Chi tiêu gia đình phụ thuộc tuổi, thu nhập và mối quan hệ giữa thành viên. Phân tích theo bối cảnh cụ thể giúp dự báo nhu cầu tốt hơn nhãn thế hệ.','Cùng 30 tuổi, người sống một mình và người có con nhỏ có thể ưu tiên diện tích nhà, bảo hiểm và thời gian khác nhau.','Khác biệt giữa hai người có thể do vòng đời hoặc thu nhập, không nhất thiết do thế hệ.')
add(4,'Nghề nghiệp và tình trạng kinh tế',179,180,'Nghề nghiệp liên quan điều kiện làm việc, thu nhập, địa vị và nhu cầu sản phẩm; có thể dùng như một căn cứ phân khúc.||Tình trạng kinh tế ảnh hưởng khả năng chi trả và mức ưu tiên. Khi vận dụng, xét thu nhập khả dụng, nghĩa vụ chi tiêu, dự trữ và khả năng vay; đây là gợi ý phân tích bổ trợ cho đề mục slide 180.||Kết hợp nhu cầu công việc và ngân sách để thiết kế gói sản phẩm, phương thức mua và dịch vụ phù hợp.','Kỹ sư thiết kế cần laptop đồ họa; sinh viên ưu tiên giá và độ bền. Nhu cầu cấu hình phải đi cùng khả năng chi trả.','Nghề nghiệp không chỉ tác động qua thu nhập; còn qua nhiệm vụ, môi trường và chuẩn mực nghề.')
add(4,'Quan niệm bản thân và định vị',181,188,'Quan niệm bản thân là suy nghĩ và cảm xúc của cá nhân về chính mình. Hai chiều thực tế/lý tưởng và riêng tư/xã hội giúp nhận diện các cách tự nhìn nhận.||Sản phẩm có thể duy trì hình ảnh hiện tại hoặc giúp hướng tới hình ảnh mong muốn. Tài sản có thể trở thành một phần bản sắc; hiệu ứng sở hữu làm tăng giá trị chủ quan sau khi sở hữu.||Đo bằng các cặp tính từ đối cực và đối chiếu hình ảnh thương hiệu. Truyền thông cần tránh khai thác cảm giác tự ti hoặc chuẩn đẹp phi thực tế.','Một người xem mình sống xanh chọn bình tái sử dụng để thể hiện và duy trì bản sắc đó.','Bản thân lý tưởng là điều muốn trở thành; bản thân xã hội gắn cách nhìn trong quan hệ với người khác.')
add(4,'Lối sống, đo lường và VALS',189,197,'Lối sống phản ánh cách con người sống và phân bổ thời gian, nguồn lực. Nghiên cứu xem hoạt động, sở thích, quan điểm, thái độ, giá trị và truyền thông.||Phân biệt lối sống chung của một nhóm với lối sống gắn một sản phẩm/hoạt động. Kết hợp nhân khẩu học và tâm lý giúp hiểu rõ hơn khách hàng.||VALS sử dụng động lực định hướng và nguồn lực; slide phân biệt lý tưởng, thành tích và tự thể hiện. Các tỷ lệ phong cách sống quốc tế trong slide là dữ liệu được trích trong tài liệu, không phải tỷ lệ hiện tại của Việt Nam.','Hai người cùng thu nhập nhưng một người dành thời gian cho thể thao, người kia cho game: cùng nhân khẩu học chưa chắc cùng lối sống.','VALS không chỉ phân loại bằng thu nhập; không dùng ví dụ tương tác như công cụ chẩn đoán chuẩn hóa.')
add(4,'Cá tính và hành vi khách hàng',198,200,'Cá tính gồm những nét tương đối ổn định như tự tin, độc lập, năng động, thận trọng, cởi mở. Bảng 16 cặp tính cách trong slide là tài liệu đối chiếu.||Doanh nghiệp có thể cân nhắc cá tính trong phân khúc và truyền thông khi chứng minh được liên hệ với lựa chọn sản phẩm.||Phân tích tốt cần phối hợp cá tính với tình huống, nhu cầu và nguồn lực, thay vì gắn một tính cách với duy nhất một thương hiệu.','Khách thận trọng có thể quan tâm bảo hành và dùng thử; khách thích khám phá có thể chú ý sản phẩm mới.','Cá tính tương đối ổn định; tâm trạng nhất thời không đủ để kết luận cá tính.')
add(5,'Quyết định danh nghĩa, hạn chế và mở rộng',204,210,'Danh nghĩa gắn mức tham gia thấp và hành vi theo thói quen hoặc trung thành; ít tìm kiếm và so sánh mới.||Hạn chế xem một vài phương án, thuộc tính và dùng quy tắc đơn giản. Mở rộng gồm tìm kiếm nội/ngoại bộ sâu, đánh giá nhiều lựa chọn và quan tâm sau mua.||Mức tham gia phụ thuộc tầm quan trọng, rủi ro, kinh nghiệm, sản phẩm và tình huống; không chỉ phụ thuộc giá.','Mua nước quen: danh nghĩa; đổi nhãn tai nghe phổ thông: có thể hạn chế; mua căn nhà đầu tiên: thường mở rộng.','Mua lại vì tiện chưa chắc là trung thành có cam kết mạnh với thương hiệu.')
add(5,'Nhận biết vấn đề và nghiên cứu nhu cầu',211,224,'Nhận biết vấn đề xuất hiện khi khoảng cách giữa trạng thái mong muốn và thực tế đủ quan trọng để kích hoạt quyết định.||Vấn đề đã kích hoạt được khách tự nhận ra; vấn đề chưa kích hoạt cần được làm rõ. Doanh nghiệp có thể nghiên cứu hoạt động, sản phẩm, vấn đề và cảm xúc qua phỏng vấn, nhóm tập trung hoặc khảo sát.||Chiến lược gồm khám phá vấn đề, đáp ứng bằng marketing phù hợp, giúp nhận ra vấn đề chung hoặc chọn lọc. Cần phản ánh lợi ích thật, tránh phóng đại nỗi lo.','Điện thoại hết pin giữa ngày tạo khoảng cách với mong muốn dùng liên tục; giải pháp có thể là pin tốt hơn, sạc tiện hơn hoặc hỗ trợ kỹ thuật.','Khoảng cách chưa đủ lớn hoặc không được khách quan tâm thì chưa chắc dẫn tới mua.')
add(5,'Tìm kiếm thông tin và đánh giá lựa chọn',225,238,'Quá trình mua gồm nhận biết nhu cầu, tìm thông tin, đánh giá, quyết định và sau mua. Tìm nội bộ là truy xuất trí nhớ; tìm ngoài gồm cá nhân, thương mại, công cộng và trải nghiệm.||Mức tìm kiếm phụ thuộc đặc tính người mua, sản phẩm, tình huống và thời gian. Cần phân biệt nguồn thông tin với nội dung đang tìm như nhãn hiệu, cửa hàng hoặc thuộc tính.||Đánh giá gồm tiêu chí chức năng và tâm lý xã hội. Marketer có thể cải tiến sản phẩm, làm rõ thuộc tính hoặc thay đổi niềm tin thiếu chính xác bằng chứng cứ.','Khách nhớ trải nghiệm laptop cũ rồi xem đánh giá, hỏi bạn và thử tại cửa hàng; so pin, hiệu năng, trọng lượng và hình ảnh cá nhân.','Quảng cáo là nguồn thương mại; lời khuyên bạn bè là nguồn cá nhân, dù cả hai có thể nói về cùng một thuộc tính.')
add(5,'Quyết định và hành vi sau mua',239,241,'Ý định mua có thể bị thay đổi bởi quan điểm người khác, hoàn cảnh và hoạt động marketing. Tồn kho, thanh toán hoặc dịch vụ có thể là rào cản.||Sau mua, khách đánh giá trải nghiệm so với kỳ vọng, tìm cách củng cố quyết định và có thể hài lòng hoặc không hài lòng.||Không hài lòng có thể dẫn đến thụ động, phàn nàn, tức giận hoặc hành động khác. Xử lý sau mua giúp giải quyết vấn đề và cung cấp dữ liệu cải tiến.','Khách chọn máy ảnh nhưng hết hàng nên đổi thương hiệu. Sau mua, hướng dẫn sử dụng và hỗ trợ giúp giảm bất an.','Không phàn nàn không đồng nghĩa hài lòng; khách có thể im lặng rồi rời bỏ.')
add(5,'Chấp nhận sản phẩm mới',242,246,'Năm giai đoạn: biết → để ý → đánh giá → dùng thử → chấp nhận. Mỗi bước cần loại hỗ trợ khác nhau.||Nhóm cách tân và chấp nhận sớm đi trước; đa số cần bằng chứng rõ và rủi ro thấp hơn; nhóm muộn thường thận trọng.||Tốc độ chấp nhận chịu ảnh hưởng lợi thế nổi trội, tương hợp, dễ sử dụng, dễ dùng thử và dễ quan sát/mô tả kết quả.','Ứng dụng mới giới thiệu công dụng, cung cấp demo, cho thử gói nhỏ rồi hướng dẫn dùng lâu dài.','Biết đến sản phẩm chưa có nghĩa đã chấp nhận sử dụng thường xuyên.')
add(6,'Thị trường và đặc điểm khách hàng tổ chức',250,256,'Khách hàng tổ chức mua để sản xuất, cung cấp dịch vụ, bán lại hoặc thực hiện chức năng. Gồm doanh nghiệp sản xuất, thương mại và tổ chức nhà nước theo bài giảng.||Sản phẩm gồm thiết bị, phụ trợ, bộ phận, nguyên liệu và dịch vụ. Thị trường thường ít khách nhưng lượng mua lớn, tập trung địa lý và quan hệ trực tiếp.||Nhu cầu thứ phát bắt nguồn từ nhu cầu thị trường tiêu dùng. Mua chuyên nghiệp, theo quy trình và nhiều người tham gia; trong ngắn hạn cầu có thể ít co giãn theo giá như slide.','Nhu cầu mua bao bì của nhà máy tăng vì đơn hàng sản phẩm cuối tăng: cầu thứ phát.','Ít co giãn theo giá không có nghĩa giá không quan trọng hoặc mọi loại cầu tổ chức luôn không đổi.')
add(6,'Mô hình kích thích, tổ chức và phản ứng mua',257,261,'Kích thích marketing và môi trường đi vào tổ chức, được xử lý qua trung tâm mua và quy trình ra quyết định, rồi tạo phản ứng mua.||Trung tâm mua là tập hợp người tham gia; quy trình mua là chuỗi hoạt động. Cả hai chịu yếu tố môi trường, tổ chức, tương tác và cá nhân.||Bốn câu hỏi: mua gì/quyết định nào, ai tham gia, yếu tố nào ảnh hưởng và quyết định như thế nào. Dùng chúng để lập bản phân tích khách hàng B2B.','Nhà cung cấp gửi đề xuất; kỹ thuật kiểm tra tương thích, tài chính kiểm tra ngân sách, ban lãnh đạo phê duyệt trước khi đặt hàng.','Tổ chức có quy trình không có nghĩa quyết định hoàn toàn không chịu cảm xúc hoặc quan hệ.')
add(6,'Bốn nhóm nhân tố ảnh hưởng mua B2B',262,270,'Môi trường: nhu cầu thị trường, triển vọng kinh tế, vốn, cung nguyên liệu, công nghệ, chính trị, cạnh tranh và văn hóa.||Tổ chức: mục tiêu, chiến lược, cơ cấu, chính sách, quy trình và giới hạn mua. Tương tác cá nhân: quyền lực, thẩm quyền, đồng cảm, sức thuyết phục và động lực nhóm.||Cá nhân: tuổi, thu nhập, học vấn, nghề nghiệp, tính cách và thái độ rủi ro. Khi phân tích, nêu dữ kiện rồi xác định cơ chế tác động và phản ứng mua có thể xảy ra.','Ngân sách do công ty quy định: tổ chức. Trưởng phòng thuyết phục hội đồng: tương tác. Người mua ngại rủi ro: cá nhân.','Phân loại theo cấp độ nguyên nhân, không chỉ thấy có người xuất hiện là gán cho yếu tố cá nhân.')
add(7,'Ba dạng mua, đấu thầu và hợp đồng dài hạn',274,281,'Mua mới cần nhiều thông tin, người tham gia và thời gian. Mua lặp lại không thay đổi giữ nguyên các điều kiện. Mua lặp lại có điều chỉnh thay thông số hoặc điều kiện đơn hàng.||Đấu thầu gồm mời thầu, nhận đề xuất, đánh giá và lựa chọn theo giá, chất lượng, năng lực, tiến độ. Giá thấp nhất chưa chắc tạo giá trị tổng thể cao nhất.||Hợp đồng dài hạn tăng ổn định nguồn cung, giảm chi phí mua lại và hỗ trợ hợp tác, đổi lại tăng cam kết và phụ thuộc. Đấu thầu có thể là bước lựa chọn trước hợp đồng dài hạn.','Nhà máy đặt cùng nguyên liệu: lặp lại không đổi; yêu cầu đổi chuẩn vật liệu: lặp lại điều chỉnh; mua dây chuyền lần đầu: mua mới.','Ba dạng hành vi mua khác với hình thức đấu thầu/hợp đồng; chúng không phải cùng một tiêu chí phân loại.')
add(7,'Tám bước ra quyết định mua tổ chức',282,289,'1 Nhận thức vấn đề; 2 Phác họa tổng quát nhu cầu; 3 Xác định chi tiết kỹ thuật; 4 Tìm nhà cung cấp.||5 Yêu cầu chào hàng; 6 Lựa chọn nhà cung cấp; 7 Đặt hàng; 8 Đánh giá kết quả. Mua mới thường cần xử lý đầy đủ hơn; mua lặp lại có thể rút gọn.||Bước lựa chọn xét hiệu suất, kinh tế, thích hợp, thích nghi và pháp lý. Bước đặt hàng làm rõ số lượng, chất lượng, giá, giao nhận, thanh toán; bước cuối lấy phản hồi và đo hiệu quả.','Theo bảng slide 287, tổng có trọng số A=49, B=56, C=37; B cao nhất trong mô hình và dữ liệu đã cho.','Phác họa nhu cầu là xác định đặc điểm chung; đặc tả kỹ thuật chuyển thành yêu cầu cụ thể để đánh giá.')
add(7,'Trung tâm mua và các vai trò',290,294,'Các vai trò được liệt kê: khởi xướng, gác cửa, sử dụng, ảnh hưởng, mua, phê duyệt và quyết định. Một người có thể giữ nhiều vai trò.||Người gác cửa kiểm soát dòng thông tin/tiếp cận; người ảnh hưởng định hình tiêu chí; người mua thương lượng và giao dịch; người quyết định lựa chọn phương án.||Giá trị, độ phức tạp và rủi ro tăng thường làm tăng số người tham gia. Cần xác định từng người ảnh hưởng đến quyết định nào, dùng tiêu chuẩn gì.','Mua phần mềm: nhân viên đề xuất, IT đặt chuẩn bảo mật, trợ lý lọc lịch nhà cung cấp, thu mua đàm phán, lãnh đạo duyệt.','Trung tâm mua không nhất thiết là một phòng ban cố định, và không chỉ gồm nhân viên phòng mua hàng.')
add(7,'Phân tích giá trị, tự làm, JIT và mua đồng bộ',295,301,'Phân tích nhà cung cấp dựa chất lượng, năng lực, giá/thanh toán, giao hàng và hỗ trợ. Giá trị xét lợi ích trên tổng chi phí cùng mức phù hợp nhu cầu.||Tự sản xuất tăng chủ động công nghệ và chất lượng nhưng cần vốn/năng lực; mua ngoài giảm đầu tư và tiếp cận chuyên môn nhưng tạo phụ thuộc.||JIT giao đúng lượng, đúng thời điểm để giảm tồn kho; đòi hỏi chất lượng và giao hàng tin cậy. Mua đồng bộ gộp sản phẩm, hệ thống và dịch vụ qua một đầu mối chịu trách nhiệm.','Phần mềm giá rẻ nhưng triển khai và bảo trì đắt có thể có tổng chi phí cao. JIT gặp giao trễ có thể khiến dây chuyền ngừng.','Giá mua không phải toàn bộ chi phí; JIT không đồng nghĩa bỏ qua tồn kho an toàn trong mọi hoàn cảnh.')
